130:   function update(dt){
131:     if(!running)return;
132:     elapsed=(performance.now()-startedAt)/1000;
133:     const accelerating=keys.ArrowUp||keys.KeyW||touch.accelerate;
134:     const braking=keys.ArrowDown||keys.KeyS;
135:     const left=keys.ArrowLeft||keys.KeyA||touch.left,right=keys.ArrowRight||keys.KeyD||touch.right;
136:     const drifting=keys.Space||touch.drift;
137:     const turn=(right?1:0)-(left?1:0);
138:     const max=MAX_SPEED+(player.boost>0?60:0);
139:     player.speed += (accelerating?105:45)*dt;
140:     if(braking)player.speed-=150*dt;
