160:       o.used=true;if(o.type==='coin'){player.coins=Math.min(99,player.coins+1);player.speed=Math.min(MAX_SPEED+45,player.speed+3);showToast('+1 MOEDA')}
161:       else{player.item=['turbo','turbo','shield'][Math.floor(Math.random()*3)];ui.item.querySelector('.item-icon').textContent=player.item==='turbo'?'⚡':'◉';showToast('ITEM PRONTO!')}
